from __future__ import annotations
from math import log2

def profile(q: int, length: int) -> tuple[int, float | None]:
    if q < 0 or length < 0:
        raise ValueError("parameters must be nonnegative")
    count = q ** length
    return count, log2(count) if count else None

def main() -> None:
    for q, length in [(2, 5), (4, 3), (3, 3), (10, 10)]:
        count, bits = profile(q, length)
        print(f"q={q}, L={length}: {count:,} candidates; {bits:.6f} bits")

if __name__ == "__main__":
    main()

from __future__ import annotations

def compression_table(max_n: int) -> list[tuple[int, int, int, int]]:
    if max_n < 0:
        raise ValueError("max_n must be nonnegative")
    return [(n, 2**n, 2**n - 1, 1) for n in range(max_n + 1)]

def main() -> None:
    print("n  objects  shorter descriptions  deficit")
    for n, objects, shorter, deficit in compression_table(12):
        print(f"{n:2d} {objects:8d} {shorter:20d} {deficit:8d}")

if __name__ == "__main__":
    main()

